// Resolve the addresses online, instead of guessing coordinates. Only accept Seoul results with the matching district.
async function locateIve(){
 for(const rec of supplied){
  const found=demoPlaces.find(x=>x.id===rec.id);
  if(!found||Number.isFinite(found.lat)&&Number.isFinite(found.lng))continue;
  try{
   const u='https://nominatim.openstreetmap.org/search?'+new URLSearchParams({q:rec.address,format:'json',limit:'3',countrycodes:'kr'});
   const resp=await fetch(u,{headers:{'Accept':'application/json'}});
   if(!resp.ok)continue;
   const matches=await resp.json();
   const candidate=matches.find(v=>(v.display_name||'').includes('서울')&&(v.display_name||'').includes(rec.areaKo));
   if(!candidate)continue;
   const lat=Number(candidate.lat),lng=Number(candidate.lon);
   if(!Number.isFinite(lat)||!Number.isFinite(lng)||lat<37.3||lat>37.8||lng<126.7||lng>127.3)continue;
   for(const list of [demoPlaces,window.OSHI_PLACES]){const p=list?.find(x=>x.id===rec.id);if(p){p.lat=lat;p.lng=lng;p.coordinateSource='online-address-geocoding-unverified';}}
   if(typeof selectedGroup!=='undefined'&&selectedGroup==='IVE'&&typeof renderSpots==='function')renderSpots();
  }catch(e){/* Browser offline / geocoder blocked: retain address only */}
 }
}
setTimeout(()=>{void locateIve()},1000);
